pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    let doublings = attempt.saturating_sub(1);
    let multiplier = 1u64
        .checked_shl(doublings)
        .unwrap_or(u64::MAX);
    let raw = config.base_delay_ms.saturating_mul(multiplier);
    raw.min(config.max_delay_ms)
}

